-- ============================================
-- E-Commerce Sample Database (Synthetic Data)
-- Generated for practice with pgAdmin / PostgreSQL
-- Tables: p2_users, p2_orders, p2_order_items, p2_returns
-- ============================================

DROP TABLE IF EXISTS p2_returns;
DROP TABLE IF EXISTS p2_order_items;
DROP TABLE IF EXISTS p2_orders;
DROP TABLE IF EXISTS p2_users;

CREATE TABLE p2_users (
    user_id     INTEGER PRIMARY KEY,
    region      VARCHAR(20),
    channel     VARCHAR(20),
    signup_dt   TIMESTAMP
);

CREATE TABLE p2_orders (
    order_id        INTEGER PRIMARY KEY,
    user_id         INTEGER REFERENCES p2_users(user_id),
    region          VARCHAR(20),
    device          VARCHAR(10),
    order_dt        TIMESTAMP,
    gmv             NUMERIC(10,2),
    discount        NUMERIC(10,2),
    cogs            NUMERIC(10,2),
    shipping_cost   NUMERIC(10,2)
);

CREATE TABLE p2_order_items (
    item_id     SERIAL PRIMARY KEY,
    order_id    INTEGER REFERENCES p2_orders(order_id),
    sku         VARCHAR(20),
    price       NUMERIC(10,2),
    qty         INTEGER
);

CREATE TABLE p2_returns (
    order_id    INTEGER REFERENCES p2_orders(order_id),
    reason      VARCHAR(30),
    return_dt   TIMESTAMP
);

